import 'package:flutter/material.dart';
import '../services/api_service.dart';

class AnalyticsScreen extends StatefulWidget { final String token; const AnalyticsScreen({super.key, required this.token}); @override State<AnalyticsScreen> createState() => _AnalyticsScreenState(); }
class _AnalyticsScreenState extends State<AnalyticsScreen> { Map<String, dynamic>? _data; String? _error; @override void initState() { super.initState(); _load(); } Future<void> _load() async { try { final data = await ApiService(token: widget.token).fetchAnalytics(); if (mounted) setState(() => _data = data); } catch (_) { if (mounted) setState(() => _error = 'Unable to load analytics.'); } }
@override Widget build(BuildContext context) { final data = _data; if (data == null) return Container(color: const Color(0xFF070B1E), child: Center(child: _error == null ? const CircularProgressIndicator() : Text(_error!, style: const TextStyle(color: Colors.white54)))); final total = data['total'] as int; final complete = data['completed'] as int; final percent = (data['completion_percentage'] as num).toDouble() / 100; return Container(color: const Color(0xFF070B1E), child: ListView(padding: const EdgeInsets.all(16), children: [const Text('Analytics', style: TextStyle(color: Colors.white, fontSize: 28, fontWeight: FontWeight.bold)), const SizedBox(height: 20), Center(child: SizedBox(width: 150, height: 150, child: Stack(alignment: Alignment.center, children: [CircularProgressIndicator(value: percent, strokeWidth: 14, backgroundColor: Colors.white12, valueColor: const AlwaysStoppedAnimation(Color(0xFF22C55E))), Text('${data['completion_percentage']}%', style: const TextStyle(color: Colors.white, fontSize: 24, fontWeight: FontWeight.bold))]))), const SizedBox(height: 20), _tile('Total tasks', '$total'), _tile('Completed', '$complete'), _tile('Pending', '${data['pending']}'), _tile('Average tasks per day', '${data['average_tasks_per_day']}'), const SizedBox(height: 12), const Text('Weekly and monthly productivity are based on completion history as tasks are completed.', style: TextStyle(color: Colors.white54))])); }
Widget _tile(String label, String value) => Container(margin: const EdgeInsets.only(bottom: 10), padding: const EdgeInsets.all(16), decoration: BoxDecoration(color: const Color(0xFF111B3A), borderRadius: BorderRadius.circular(16)), child: Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [Text(label, style: const TextStyle(color: Colors.white70)), Text(value, style: const TextStyle(color: Colors.white, fontSize: 20, fontWeight: FontWeight.bold))])); }
